curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{"query":"{ __schema { queryType { fields { name args { name type { name kind ofType { name kind ofType { name kind } } } } } } } }"}' | python3 -c "
import json,sys
data = json.load(sys.stdin)
for f in data['data']['__schema']['queryType']['fields']:
    if f['name']=='documents':
        for a in f['args']:
            if a['name']=='orderBy':
                print(json.dumps(a['type'], indent=2))
"
